options.afterRender:
// Europe's cross-border flows as a directed graph that Graphviz lays out in
// this browser: an arrow per border from the country that sends to the one
// that receives, as thick as the flow. Query E holds every border at every
// ready 15 min step, C the countries, H the net of each reporting country.
// Two layouts of the same graph: "Who powers whom" is Graphviz dot, which
// ranks the graph so arrows point down, senders on top and receivers below;
// "Where" is neato started from the countries' positions on the map. The slider
// runs the two days; letting go of it moves the map and the charts to that
// step. Clicking a country picks it everywhere (its borders stand out here, the
// map keeps only them, the chart below runs them over the two days); clicking
// it again, or its name in the bar, lets it go.
const VIZ = 'https://cdn.jsdelivr.net/npm/@viz-js/viz@3.30.0/dist/viz.js';
const self = this;
const theme = context.grafana.theme;
// Graphviz reads #rrggbb or #rrggbbaa, not the rgb() and rgba() the theme uses.
const hex = (css) => {
  const m = String(css).match(/rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)(?:[,\s/]+([\d.]+))?/);
  if (!m) {
    return css;
  }
  const byte = (v) => Math.round(Number(v)).toString(16).padStart(2, '0');
  return '#' + byte(m[1]) + byte(m[2]) + byte(m[3]) + (m[4] === undefined ? '' : byte(Number(m[4]) * 255));
};
const TEXT = hex(theme.colors.text.primary);
const MUTED = hex(theme.colors.text.secondary);
// Sends (net export) and receives (net import), from pale to full with the GW.
const SEND = theme.isDark ? ['#1c3b3a', '#2a9d8f'] : ['#d7efec', '#2a9d8f'];
const TAKE = theme.isDark ? ['#4a3517', '#e9a23b'] : ['#fbecd2', '#e9a23b'];

const root = context.element.querySelector('.grid');
if (!root) {
  return;
}
context.element.style.height = '100%';
// The bar is built here: the panel sanitizes its content, and buttons and
// inputs written there would not survive it.
if (!root.querySelector('.grid-bar')) {
  root.innerHTML =
    '<div class="grid-bar"><span class="grid-engine">' +
    '<button data-engine="dot" title="Graphviz dot: senders on top, receivers below">Who powers whom</button>' +
    '<button data-engine="neato" title="Graphviz neato, started from the map">Where</button></span>' +
    '<button class="grid-play" title="Run the two days">▶</button>' +
    '<input class="grid-step" type="range" min="0" max="0" step="1" value="0"><span class="grid-when"></span>' +
    '<button class="grid-pick" title="Let the country go"></button></div>' +
    '<div class="grid-graph"></div><div class="grid-note"></div>';
}
const box = root.querySelector('.grid-graph');
const slider = root.querySelector('.grid-step');
const when = root.querySelector('.grid-when');
const note = root.querySelector('.grid-note');
const chip = root.querySelector('.grid-pick');
const setVars = (vars) => context.grafana.locationService.partial(vars, true);
// The country picked here, on the ranking or in a shared link.
const picked = context.grafana.replaceVariables('${country}');

const rowsOf = (refId) => {
  const frame = (context.panelData?.series ?? []).find((f) => f.refId === refId);
  if (!frame || !frame.fields.length) {
    return null;
  }
  const n = frame.length ?? frame.fields[0].values.length;
  return Array.from({ length: n }, (_, i) =>
    Object.fromEntries(frame.fields.map((f) => [f.name, f.values[i] ?? f.values.get?.(i)])),
  );
};
// While a query runs again the panel can be handed frames without their
// fields: keep what was drawn.
const edgeRows = rowsOf('E')?.filter((r) => r.a && r.b && Number.isFinite(r.gw) && r.time != null);
const countryRows = rowsOf('C')?.filter((r) => r.iso && r.name);
if (!edgeRows?.length || !countryRows?.length) {
  if (self.svg && self.svg.parentNode !== box) {
    box.replaceChildren(self.svg);
  } else if (!self.svg) {
    box.textContent = 'No flows yet.';
  }
  return;
}
const countries = new Map(countryRows.map((c) => [c.iso, c]));
const byStep = new Map();
for (const e of edgeRows) {
  const t = Number(e.time);
  if (!byStep.has(t)) {
    byStep.set(t, []);
  }
  byStep.get(t).push(e);
}
const nets = new Map();
for (const h of rowsOf('H') ?? []) {
  nets.set(`${Number(h.time)}|${h.iso}`, h.net);
}
const steps = [...byStep.keys()].sort((x, y) => x - y);

const quote = (s) => `"${String(s).replace(/["\\]/g, '\\$&')}"`;
const html = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const mix = ([from, to], k) => {
  const p = (h) => [1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16));
  const [a, b] = [p(from), p(to)];
  return '#' + a.map((v, i) => Math.round(v + (b[i] - v) * k).toString(16).padStart(2, '0')).join('');
};
const gw = (v) => `${Math.abs(v) < 9.95 ? Math.abs(v).toFixed(1) : Math.round(Math.abs(v))} GW`;

// The graph at one step. A border under 50 MW is left out: it carries next to
// nothing either way. The net of a reporting country is its own total; that
// of any other country is the sum over the borders reported here, so a dashed
// outline marks it as partial.
const source = (t, engine) => {
  const edges = byStep.get(t).filter((e) => Math.abs(e.gw) >= 0.05);
  const net = new Map();
  for (const e of edges) {
    net.set(e.a, (net.get(e.a) ?? 0) + e.gw);
    net.set(e.b, (net.get(e.b) ?? 0) - e.gw);
  }
  for (const iso of net.keys()) {
    const own = nets.get(`${t}|${iso}`);
    if (Number.isFinite(own)) {
      // Energy-Charts: positive is import. Here: positive is what it sends.
      net.set(iso, -own);
    }
  }
  const top = Math.max(1, ...[...net.values()].map(Math.abs));
  const dot = [
    'digraph flows {',
    engine === 'dot'
      ? '  layout=dot; rankdir=TB; nodesep=0.25; ranksep=0.45; splines=true;'
      : '  layout=neato; mode=major; overlap=false; sep="+12"; splines=true;',
    `  bgcolor="transparent"; pad=0.2; fontname="Helvetica";`,
    `  node [shape=box style="rounded,filled" penwidth=1.2 margin="0.08,0.04" fontname="Helvetica" fontsize=10 fontcolor=${quote(TEXT)}];`,
    `  edge [color=${quote(MUTED)} fontname="Helvetica" fontsize=8 fontcolor=${quote(MUTED)} arrowsize=0.6];`,
  ];
  for (const iso of [...net.keys()].sort()) {
    const c = countries.get(iso);
    if (!c) {
      continue;
    }
    const v = net.get(iso);
    const k = Math.min(1, Math.abs(v) / top);
    const fill = mix(v >= 0 ? SEND : TAKE, 0.15 + 0.85 * k);
    // Dark text on a light fill, light text on a dark one.
    const [r, g, b] = [1, 3, 5].map((i) => parseInt(fill.slice(i, i + 2), 16));
    const ink = 0.299 * r + 0.587 * g + 0.114 * b > 140 ? '#111111' : '#f2f2f2';
    const own = c.hub && Number.isFinite(nets.get(`${t}|${iso}`));
    const verb = v >= 0 ? 'sends' : 'takes';
    // Graphviz neato reads pos as where to start; inches, east-west shrunk by cos 50°.
    const pos = engine === 'dot' ? '' : ` pos="${(c.lng * 0.64 * 0.45).toFixed(2)},${(c.lat * 0.45).toFixed(2)}"`;
    dot.push(
      `  ${quote(iso)} [id=${quote('c-' + iso)} label=<<B>${html(c.name)}</B><BR/><FONT POINT-SIZE="8">${verb} ${gw(v)}${own ? '' : '*'}</FONT>> ` +
        `fillcolor=${quote(fill)} fontcolor=${quote(ink)} color=${quote(own ? fill : MUTED)}${own ? '' : ' style="rounded,filled,dashed"'}${pos}];`,
    );
  }
  for (const e of edges) {
    const [from, to] = e.gw > 0 ? [e.a, e.b] : [e.b, e.a];
    const w = Math.min(14, 0.6 + 2.2 * Math.abs(e.gw));
    dot.push(`  ${quote(from)} -> ${quote(to)} [id=${quote(`e-${from}-${to}`)} penwidth=${w.toFixed(2)} label=${quote(gw(e.gw))} tooltip=${quote(`${countries.get(from)?.name} → ${countries.get(to)?.name}: ${gw(e.gw)}`)}];`);
  }
  dot.push('}');
  return { dot: dot.join('\n'), edges: edges.length, nodes: net.size };
};

const fmt = new Intl.DateTimeFormat(undefined, {
  timeZone: 'Europe/Berlin', weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit',
});
const draw = () => {
  const t = steps[self.index];
  const { dot, edges, nodes } = source(t, self.engine);
  let svg;
  try {
    svg = self.viz.renderSVGElement(dot);
  } catch (err) {
    // An aborted WebAssembly instance is unusable: a new one next time.
    self.viz = null;
    box.textContent = `Graphviz did not draw this step: ${err.message ?? err}`;
    return;
  }
  svg.removeAttribute('width');
  svg.removeAttribute('height');
  svg.classList.add('grid-svg');
  // Graphviz titles show ids; the edges keep their own tooltips.
  svg.querySelectorAll('g.node > title').forEach((n) => (n.textContent = countries.get(n.textContent)?.name ?? n.textContent));
  // The picked country, its borders and its neighbours stand out.
  if (picked && svg.getElementById('c-' + picked)) {
    svg.classList.add('has-pick');
    svg.getElementById('c-' + picked).classList.add('on', 'picked');
    svg.querySelectorAll('g.edge').forEach((g) => {
      const [from, to] = g.id.slice(2).split('-');
      if (from === picked || to === picked) {
        g.classList.add('on');
        svg.getElementById('c-' + (from === picked ? to : from))?.classList.add('on');
      }
    });
  }
  svg.addEventListener('click', (ev) => {
    const node = ev.target.closest('g.node');
    if (node) {
      const iso = node.id.slice(2);
      setVars({ 'var-country': iso === picked ? '' : iso });
    }
  });
  self.svg = svg;
  box.replaceChildren(svg);
  when.textContent = `${fmt.format(new Date(t))} (Berlin)`;
  note.textContent =
    `${nodes} countries, ${edges} borders carrying 50 MW or more · ` +
    `* partial: only the borders the eight reporting countries share with it`;
};

// The bar: which layout, which step, play, and the country picked. Wired once,
// so the handlers reach the latest data through self.draw and self.steps.
const wire = () => {
  root.querySelectorAll('.grid-engine button').forEach((b) =>
    b.addEventListener('click', () => {
      self.engine = b.dataset.engine;
      root.querySelectorAll('.grid-engine button').forEach((x) => x.classList.toggle('on', x === b));
      self.draw();
    }),
  );
  const publish = () => setVars({ 'var-step': new Date(self.steps[self.index]).toISOString() });
  chip.addEventListener('click', () => setVars({ 'var-country': '' }));
  slider.addEventListener('input', () => {
    self.index = Number(slider.value);
    self.draw();
  });
  slider.addEventListener('change', publish);
  const play = root.querySelector('.grid-play');
  play.addEventListener('click', () => {
    if (self.timer) {
      clearInterval(self.timer);
      self.timer = null;
      play.textContent = '▶';
      publish();
      return;
    }
    if (self.index >= self.steps.length - 1) {
      self.index = 0;
    }
    play.textContent = '❚❚';
    self.timer = setInterval(() => {
      if (!root.isConnected || self.index >= self.steps.length - 1) {
        clearInterval(self.timer);
        self.timer = null;
        play.textContent = '▶';
        publish();
        return;
      }
      self.index += 1;
      slider.value = String(self.index);
      self.draw();
    }, 600);
  });
};

self.engine = self.engine ?? 'dot';
self.draw = draw;
self.steps = steps;
chip.textContent = picked ? `${countries.get(picked)?.name ?? picked} ×` : '';
chip.style.display = picked ? '' : 'none';
// The step picked in the URL, else the newest ready one.
const asked = Date.parse(context.grafana.replaceVariables('${step}'));
const at = Number.isFinite(asked) ? steps.findLastIndex((t) => t <= asked) : -1;
if (!self.timer) {
  self.index = at >= 0 ? at : steps.length - 1;
}
self.index = Math.min(self.index, steps.length - 1);
if (self.root !== root) {
  self.root = root;
  wire();
}
slider.max = String(steps.length - 1);
slider.value = String(self.index);
root.querySelectorAll('.grid-engine button').forEach((x) => x.classList.toggle('on', x.dataset.engine === self.engine));

if (self.viz) {
  draw();
} else {
  box.textContent = 'Loading Graphviz…';
  import(VIZ)
    .then((m) => m.instance())
    .then((viz) => {
      self.viz = viz;
      draw();
    })
    .catch((err) => (box.textContent = `Graphviz did not load: ${err.message ?? err}`));
}

options.styles:
.grid { display: flex; flex-direction: column; height: 100%; gap: 6px; }
.grid-bar { display: flex; align-items: center; gap: 8px; font-size: 12px; }
.grid-engine { display: inline-flex; border: 1px solid rgba(128, 128, 128, 0.4); border-radius: 4px; overflow: hidden; }
.grid-engine button, .grid-play { background: transparent; color: inherit; border: 0; padding: 3px 10px; font: inherit; cursor: pointer; }
.grid-engine button.on { background: rgba(128, 128, 128, 0.25); font-weight: 600; }
.grid-play { border: 1px solid rgba(128, 128, 128, 0.4); border-radius: 4px; min-width: 32px; }
.grid-step { flex: 1; min-width: 80px; accent-color: #2a9d8f; }
.grid-when { min-width: 150px; text-align: right; font-variant-numeric: tabular-nums; }
.grid-graph { flex: 1; min-height: 0; display: flex; align-items: center; justify-content: center; color: #9AA5B1; }
.grid-svg { width: 100%; height: 100%; display: block; }
.grid-note { font-size: 11px; line-height: 1.4; color: #9AA5B1; }
.grid-pick { border: 1px solid #FFE14D; color: inherit; background: rgba(255, 225, 77, 0.12); border-radius: 12px; padding: 2px 10px; font: inherit; cursor: pointer; white-space: nowrap; }
.grid-svg g.node { cursor: pointer; }
.grid-svg.has-pick g.edge:not(.on), .grid-svg.has-pick g.node:not(.on) { opacity: 0.18; }
.grid-svg g.node.picked path, .grid-svg g.node.picked polygon { stroke: #FFE14D; stroke-width: 3; stroke-dasharray: none; }

options.getOption:
// The two days, step by step. With no country picked: the power crossing the
// borders seen, in GW. With one picked: its borders, what comes in above zero
// and what goes out below, a colour per neighbour (the six that carry most;
// the rest as Other), and its net as a line. The dashed line is the step the
// graph, the map and the ranking show; clicking the chart moves them there.
// @constants begin
const STEP = 'step';
const COUNTRY = 'country';
const COLORS = ['#5794F2', '#B877D9', '#FADE2A', '#FF9830', '#73BF69', '#F2495C'];
const OTHER = 'rgba(128, 128, 128, 0.55)';
const AREA = '#2a9d8f';
const MARK = '#FFE14D';
const TZ = 'Europe/Berlin';
// @constants end
// Named here so the panel redraws when they change: ${step} ${country}

const chart = context.panel.chart;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;
const frames = context.panel.data.series;
const col = (refId, name) => {
  const frame = frames.find((f) => f.refId === refId);
  return frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : [];
};

const times = col('A', 'time').map(Number);
const totals = col('A', 'gw').map((v) => (v == null ? null : Number(v)));
const fmt = new Intl.DateTimeFormat('en-GB', { timeZone: TZ, weekday: 'short', hour: '2-digit', minute: '2-digit' });
const labels = times.map((t) => fmt.format(new Date(t)));
const country = context.grafana.replaceVariables('${' + COUNTRY + '}');
const name = col('C', 'name')[0] ?? country;
const asked = Date.parse(context.grafana.replaceVariables('${' + STEP + '}'));
const found = Number.isFinite(asked) ? times.findLastIndex((t) => t <= asked) : -1;
const at = found >= 0 ? found : times.length - 1;

let series;
if (country) {
  const bt = col('B', 'time').map(Number);
  const bn = col('B', 'neighbour');
  const bg = col('B', 'gw').map(Number);
  // Neighbours by the power that crosses, over the two days.
  const carried = new Map();
  bn.forEach((n, i) => carried.set(n, (carried.get(n) ?? 0) + Math.abs(bg[i])));
  const top = [...carried.keys()].sort((x, y) => carried.get(y) - carried.get(x)).slice(0, COLORS.length);
  const index = new Map(times.map((t, i) => [t, i]));
  const by = new Map([...top, 'Other'].map((n) => [n, times.map(() => 0)]));
  const net = times.map(() => 0);
  bn.forEach((n, i) => {
    const k = index.get(bt[i]);
    if (k !== undefined) {
      by.get(top.includes(n) ? n : 'Other')[k] += bg[i];
      net[k] += bg[i];
    }
  });
  series = [...by.entries()]
    .filter(([, v]) => v.some((x) => x !== 0))
    .map(([n, v]) => ({
      name: n,
      type: 'bar',
      stack: 'borders',
      barCategoryGap: '15%',
      data: v.map((x) => Number(x.toFixed(3))),
      itemStyle: { color: n === 'Other' ? OTHER : COLORS[top.indexOf(n)] },
    }));
  series.push({
    name: 'Net, in',
    type: 'line',
    data: net.map((x) => Number(x.toFixed(3))),
    symbol: 'none',
    lineStyle: { color: text, width: 1.5 },
    itemStyle: { color: text },
    z: 5,
  });
} else {
  series = [
    {
      name: 'Crossing the borders seen',
      type: 'line',
      data: totals,
      symbol: 'none',
      lineStyle: { width: 1.5, color: AREA },
      itemStyle: { color: AREA },
      areaStyle: { color: AREA, opacity: 0.25 },
    },
  ];
}
if (series.length && labels.length) {
  series[0].markLine = {
    silent: true,
    symbol: 'none',
    label: { show: false },
    lineStyle: { color: MARK, type: 'dashed', width: 1.5 },
    data: [{ xAxis: labels[at] }],
  };
}

const zr = chart.getZr();
zr.off('click');
zr.on('click', (e) => {
  const pixel = [e.offsetX, e.offsetY];
  if (!times.length || !chart.containPixel({ gridIndex: 0 }, pixel)) {
    return;
  }
  const x = chart.convertFromPixel({ gridIndex: 0 }, pixel)[0];
  const i = Math.max(0, Math.min(times.length - 1, Math.round(x)));
  context.grafana.locationService.partial({ ['var-' + STEP]: new Date(times[i]).toISOString() }, true);
});

return {
  animation: false,
  backgroundColor: 'transparent',
  graphic: [
    {
      type: 'text',
      left: 8,
      top: 6,
      style: {
        text: country ? `${name}: in above zero, out below, GW` : 'All borders seen, GW · pick a country to see its own',
        fill: muted,
        fontSize: 12,
      },
    },
  ],
  legend: country ? { type: 'scroll', top: 2, right: 8, width: '55%', textStyle: { color: muted }, itemWidth: 12, itemHeight: 8 } : { show: false },
  grid: { left: 8, right: 16, top: 32, bottom: 8, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    valueFormatter: (v) => (v == null ? '' : `${Number(v).toFixed(2)} GW`),
  },
  xAxis: {
    type: 'category',
    data: labels,
    axisLabel: { color: muted, hideOverlap: true },
    axisTick: { alignWithLabel: true },
    axisLine: { lineStyle: { color: muted } },
  },
  yAxis: {
    type: 'value',
    axisLabel: { color: muted },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  series,
};

visualEditor.code:
return {
  dataset: context.editor.dataset,
  series: context.editor.series,
  xAxis: {
    type: 'time',
  },
  yAxis: {
    type: 'value',
    min: 'dataMin',
  },
}

options.getOption:
// Every country at the step the graph shows, by what it sends (to the right,
// teal) or takes (to the left, amber) in all, in GW, in the colours of the
// graph. A country outside the eight that report (paler, with an asterisk)
// only counts its borders with them. Clicking a bar picks the country
// everywhere; clicking it again lets it go.
// @constants begin
const VAR = 'country';
const SEND = '#2a9d8f';
const TAKE = '#e9a23b';
// @constants end
// Named here so the panel redraws when it changes: ${country}

const chart = context.panel.chart;
const location = context.grafana.locationService;
const muted = context.grafana.theme.colors.text.secondary;
const text = context.grafana.theme.colors.text.primary;
const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
// ECharts draws a category axis bottom up: reversed, the largest sender is on top.
const isos = col('iso').reverse();
const names = col('name').reverse();
const sends = col('sends').map(Number).reverse();
const own = col('own').map(Boolean).reverse();
const picked = context.grafana.replaceVariables('${' + VAR + '}');

chart.off('click');
chart.on('click', (event) => {
  const id = isos[event.dataIndex];
  const same = id === context.grafana.replaceVariables('${' + VAR + '}');
  location.partial({ ['var-' + VAR]: same ? '' : id }, true);
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 36, top: 8, bottom: 24, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const i = items[0].dataIndex;
      const v = sends[i];
      const what = `${v >= 0 ? 'sends' : 'takes'} <b>${Math.abs(v).toFixed(2)} GW</b>`;
      return `<b>${names[i]}</b> ${what}${own[i] ? '' : '<br/>only its borders with the eight that report'}`;
    },
  },
  xAxis: {
    type: 'value',
    name: '← takes · sends → GW',
    nameLocation: 'middle',
    nameGap: 22,
    nameTextStyle: { color: muted },
    axisLabel: { color: muted, formatter: (v) => String(Math.abs(v)) },
    splitLine: { lineStyle: { opacity: 0.15 } },
  },
  yAxis: {
    type: 'category',
    data: names.map((n, i) => (own[i] ? n : `${n}*`)),
    axisTick: { show: false },
    axisLine: { show: false },
    axisLabel: { color: text, fontSize: 10 },
  },
  series: [
    {
      type: 'bar',
      barWidth: '72%',
      cursor: 'pointer',
      data: sends.map((v, i) => ({
        value: Number(v.toFixed(3)),
        itemStyle: {
          color: v >= 0 ? SEND : TAKE,
          opacity: picked && picked !== isos[i] ? 0.25 : own[i] ? 1 : 0.55,
          borderRadius: v >= 0 ? [0, 3, 3, 0] : [3, 0, 0, 3],
        },
        label: { position: v >= 0 ? 'right' : 'left' },
      })),
      label: { show: true, color: muted, fontSize: 10, formatter: (p) => Math.abs(p.value).toFixed(1) },
    },
  ],
};

